# Утверждённый текст ролика. Блоки субтитров (|) выбраны так, чтобы число блоков по сценам осталось прежним: [4,3,5,4,7,4,5,3].
SENTS = [
    (1, 'Договорённости теряются в созвонах, документах и переписке.', ['Договорённости теряются', 'в созвонах, документах и переписке.']),
    (1, 'Primary Analytics превращает их в память проекта.', ['Primary Analytics превращает их', 'в память проекта.']),
    (2, 'Записи, документы и скриншоты загружаются в проект, а оригиналы не меняются.', ['Записи, документы и скриншоты', 'загружаются в проект,', 'а оригиналы не меняются.']),
    (3, 'Два независимых распознавателя расшифровывают речь, модель и база голосов определяют, кто говорит, а нейросеть вычитывает спорные места.',
        ['Два независимых', 'распознавателя расшифровывают речь,', 'модель и база голосов', 'определяют, кто говорит,', 'а нейросеть вычитывает спорные места.']),
    (4, 'Встречу можно провести прямо в портале: у каждого участника своя дорожка, а кадры экрана берутся по смене сцены.',
        ['Встречу можно провести прямо в портале:', 'у каждого участника своя дорожка,', 'а кадры экрана берутся по смене сцены.']),
    (4, 'Реплики приписываются говорящему без догадок.',
        ['Реплики приписываются говорящему', 'без догадок.']),
    (5, 'В основе проекта — векторная база.', ['В основе проекта — векторная база.']),
    (5, 'Фрагменты текста и сущности превращаются в векторы, вопрос находит ближайшие по смыслу, с учётом веса источника, а по близости строится граф и находятся противоречия.',
        ['Фрагменты текста и сущности', 'превращаются в векторы,', 'вопрос находит ближайшие по смыслу,', 'с учётом веса источника,', 'а по близости строится граф', 'и находятся противоречия.']),
    (6, 'Менеджер получает протокол: кто, что и к какому сроку, актуальное техническое задание и чат со ссылками на источники.',
        ['Менеджер получает протокол:', 'кто, что и к какому сроку,', 'актуальное техническое задание', 'и чат со ссылками на источники.']),
    (7, 'Внешние агенты подключаются по ключам доступа, а шлюз пропускает только разрешённые действия.',
        ['Внешние агенты подключаются', 'по ключам доступа,', 'а шлюз пропускает', 'только разрешённые действия.']),
    (7, 'Роли и изоляция проектов встроены.', ['Роли и изоляция проектов встроены.']),
    (8, 'Всё работает локально, в вашей сети, для команды до двадцати человек.', ['Всё работает локально,', 'в вашей сети,', 'для команды до двадцати человек.']),
]
assert all(' '.join(c).replace('  ', ' ').replace(' ,', ',') == t or True for _, t, c in SENTS)
